#!/bin/bash
[[ "$#" -ne 2 ]] && { echo "Usage: $0 <file1> <file2>"; exit 1; }

file1="$1"
file2="$2"

[[ ! -e "$file1" ]] && { echo "Error: First file '$file1' does not exist."; exit 1; }
[[ ! -f "$file1" ]] && { echo "Error: First path '$file1' is not a regular file."; exit 1; }
[[ ! -r "$file1" ]] && { echo "Error: First file '$file1' is not readable."; exit 1; }
[[ ! -w "$file1" ]] && { echo "Error: First file '$file1' is not writable."; exit 1; }

[[ ! -e "$file2" ]] && { echo "Error: Second file '$file2' does not exist."; exit 1; }
[[ ! -f "$file2" ]] && { echo "Error: Second path '$file2' is not a regular file."; exit 1; }
[[ ! -r "$file2" ]] && { echo "Error: Second file '$file2' is not readable."; exit 1; }

header="--- Content from $(basename "$file2") ---"

echo "$header" >> "$file1" || { echo "Error: Failed to write header to '$file1'."; exit 1; }

cat "$file2" >> "$file1" || { echo "Error: Failed to append '$file2' to '$file1'."; exit 1; }

[[ $? -eq 0 ]] && [[ -s "$file1" ]] && echo "Successfully appended '$file2' to '$file1'."

[[ ! -s "$file1" ]] && { echo "Warning: '$file1' is now empty or became empty unexpectedly."; }

