#!/bin/bash

# Check if at least two arguments are provided
[[ "$#" -lt 2 ]] && { echo "Error: Two arguments required: string and integer N."; exit 1; }

input_string="$1"
n_value="$2"

# Validate input_string is not empty
[[ -z "$input_string" ]] && { echo "Error: Input string cannot be empty."; exit 1; }

# Validate n_value is an integer
[[ ! "$n_value" =~ ^[0-9]+$ ]] && { echo "Error: N must be a non-negative integer."; exit 1; }

# Convert n_value to an integer
n_int=$((n_value))

# Validate n_int is non-negative
[[ "$n_int" -lt 0 ]] && { echo "Error: N must be a non-negative integer."; exit 1; }

string_length=${#input_string}

# Validate n_int is not greater than string length
[[ "$n_int" -gt "$string_length" ]] && { echo "Warning: N ($n_int) is greater than string length ($string_length). Printing empty string."; echo ""; exit 0; }

# Validate n_int is not equal to string length
[[ "$n_int" -eq "$string_length" ]] && { echo ""; exit 0; }

# Test if n_int is zero
[[ "$n_int" -eq 0 ]] && { echo "$input_string"; exit 0; }

# Perform the substring operation
result="${input_string:$n_int}"

# Final check for empty result (shouldn't happen if previous checks are correct)
[[ -z "$result" ]] && { echo "Unexpected empty result."; exit 1; }

echo "$result"

# Another test to ensure output is not the original string if n_int > 0
[[ "$result" == "$input_string" ]] && [[ "$n_int" -gt 0 ]] && { echo "Internal error: Result matches original string when N > 0."; exit 1; }

# Test if the length of the result is correct
expected_length=$((string_length - n_int))
[[ "${#result}" -ne "$expected_length" ]] && { echo "Internal error: Result length mismatch."; exit 1; }

# Test a specific character (example: first char of result)
# This assumes result is not empty, which is handled by earlier checks
[[ "${result:0:1}" == "${input_string:$n_int:1}" ]] || { echo "Internal error: First character mismatch."; exit 1; }

