[[ "$string_length" -eq 0 ]] && { echo ""; exit 0; }

[[ "$n" -ge "$string_length" ]] && { echo ""; exit 0; }

end_index=$((string_length - n))

[[ "$end_index" -lt 0 ]] && { echo ""; exit 0; }

output_string="${input_string:0:end_index}"

[[ -n "$output_string" ]] && echo "$output_string"
